import datetime,json,pathlib,shutil
root=pathlib.Path(__file__).resolve().parent
raw=root/'raw/final'
data=json.loads((raw/'results.json').read_text(encoding='utf-8'))
gate=(raw/'qa-gate.json').read_text(encoding='utf-8-sig').strip()
g=json.loads(gate)
records=[]
def walk(suite):
    for spec in suite.get('specs',[]):
        for test in spec.get('tests',[]):
            title=spec['title']
            identifier='E2E-01' if title.startswith('Metrics:') else 'E2E-06' if title.startswith('Ads ') else 'E2E-05' if 'fractional' in title else 'E2E-02' if 'design persists' in title else 'E2E-03' if 'undo, page ordering' in title else 'E2E-04'
            results=test.get('results',[])
            records.append((identifier,test['projectName'],test.get('status'),sum(r.get('duration',0) for r in results),[e.get('message','') for r in results for e in r.get('errors',[])]))
    for child in suite.get('suites',[]):walk(child)
for suite in data['suites']:walk(suite)
assert len(records)==18, len(records)
lines=['# Informe de QA — bloque de fundamentos, métricas y marca','',f'Fecha: {datetime.datetime.now().astimezone().isoformat(timespec="seconds")}.', '',f'**Estado del bloque: {g["verdict"]}.** URL auditada: `http://localhost:8080`. Chromium en escritorio 1440×900, móvil 375×812 y móvil 360×740.','', 'Plan: [improvement-plan.md](../../improvement-plan.md) · [test-plan.md](../../test-plan.md). Alcance: T-03, T-04–08 y coherencia de marca de T-21; T-09–20, gestión avanzada de Ads y constructor avanzado de informes permanecen pendientes. La iniciativa global sigue en progreso.','','## Veredicto determinista','','```json',gate,'```','',f'Automáticos: {g["counts"]["passed"]}/18 pasan. Fallos: {g["counts"]["failed"]}; flaky: {g["counts"]["flaky"]}; omitidos: {g["counts"]["skipped"]}. Se ejecutaron los 18 casos canónicos, con un worker y sin reintentos automáticos.','','## Cobertura y entorno','','`ledger-lint.py`: 0 incoherencias y 0 avisos. `coverage-check.py`: 0 referencias rotas, 0 tests sin referencia y 0 criterios GWT huérfanos. Los avisos restantes corresponden a T-01–02 (investigación/contrato, sin E2E propio) y T-09–20 (trabajo futuro declarado fuera de esta tanda). No se presenta cobertura E2E del alcance futuro. Evidencia textual completa en `raw/ledger-lint.txt` y `raw/coverage-check.txt`.','','Guardrail local ejecutado antes de las pruebas, exit 0. Cada tanda dispone de SQLite, caché, sesión, almacenamiento y cuatro identidades desechables propios. El bootstrap impide llamadas HTTP externas y utiliza conectores de prueba. La publicación comprobada es un borrador; no se envió a redes. No se arrancó worker ni se accedió al VPS.','','La compilación Vite y renderer pasó; conserva el aviso de tamaño de chunk >500KB. Los SHA-256 de tests y artefactos compilados figuran en `raw/final-input-hashes.json`. Las pruebas PHP/Node y OpenAPI pertenecen a las verificaciones del coordinador, no se contabilizan como ejecutadas por esta tanda. No hay bloques API-xx/A11Y-xx en este test-plan.','','## Resultados E2E','','| Escenario | Dispositivo | Resultado | Duración |','|---|---|---|---:|']
for identifier,project,status,duration,errors in sorted(records):
    lines.append(f'| {identifier} | {project} | {"PASA" if status=="expected" else "FALLA"} | {duration/1000:.1f} s |')
lines+=['','E2E-01 comprueba cero real, cobertura, fecha, comparación desigual y denominador diario. E2E-02 persiste el documento, verifica PNG 1080² y el adjunto del borrador. E2E-03 verifica historial, páginas y archivos JPEG/WebP/SVG/PDF reales; PDF con dos páginas. E2E-04 conserva trabajo local ante 409 y recupera la revisión guardada. E2E-05 registra PNG/JPEG/WebP fraccionarios (41² × 0,5 → 21²). E2E-06 conserva la marca al navegar Ads → informes y al generar el informe.','','Todos los casos Studio vigilan excepciones y errores de consola y comprueban overflow; únicamente se acepta el 409 deliberado del caso de revisión y su endpoint exacto. Métricas y marca también vigilan errores y overflow. No se excluyen errores de conexión.','','## Evidencia visual y artefactos','','Las capturas de Editor y métricas se revisaron visualmente en escritorio y móvil. El editor mantiene lienzo y herramientas dentro del ancho; en móvil apila las herramientas y requiere desplazamiento vertical. Las tarjetas muestran cero, ausencia de datos y cobertura parcial de forma diferenciada. Esta inspección no certifica toda la accesibilidad.']
for source in sorted((raw/'artifacts').glob('*/*.png')):
    if source.name not in ['studio-editor.png','metrics-quality.png']:continue
    project='mobile-360' if source.parent.name.endswith('mobile-360') else 'mobile' if source.parent.name.endswith('mobile') else 'desktop'
    short=('editor' if source.name=='studio-editor.png' else 'metrics')+'-'+project+'.png'
    shutil.copy2(source,root/'screenshots'/short)
    lines+=['',f'![{short}](screenshots/{short})']
lines+=['','Los archivos de exportación, las capturas de fallo y el contexto de error se conservan en `raw/final/artifacts/`; hashes en `raw/final/sha256.json`. El JSON real del reporter permanece íntegro en `raw/final/results.json` y se duplica en `results.json`. No se copian SQLite, cookies, contraseñas ni estados de sesión. Las trazas originales con cabeceras y cookies permanecen únicamente en el runner local aislado; `network-failures.json` conserva diagnóstico de red saneado (URL sin query, estado y error).','','## Primer intento y repetición','','El intento 1 completó 18 casos: 9 pasan y 9 fallan, 0 flaky/omitidos. `raw/attempt-1/qa-gate.json` da NO-VERDE. Dos casos fallaron por etiqueta de marca; otros detectaron rechazos de conexión en precargas JS del servidor local. Se conservan el JSON original, capturas, exportaciones y diagnóstico saneado. La etiqueta explícita se corrigió antes de repetir toda la tanda; el primer intento coincidió parcialmente con una nueva compilación. No se justificó ningún flaky ni se eliminaron fallos del JSON.']
lines+=['', 'El intento 2 con build estable terminó con 14/18 aprobados y 4 fallos de conexión; se conserva en `raw/attempt-2/`. Uno de los fallos afectó al PATCH de guardado y otro al dashboard. El coordinador aisló la conexión IPv4 rechazada mientras PHP escuchaba solo en IPv6 (`../debug-loopback/before.json`); al forzar IPv4 apareció además agotamiento de sockets por respuestas PHP sin keep-alive. El runner ahora usa un frontend Node privado en 127.0.0.1:8080 con conexiones persistentes y PHP en un puerto loopback efímero, y resuelve localhost de Chromium a 127.0.0.1. Se conserva el origen HTTP localhost y cada petición de aplicación sigue llegando a PHP. No se desactivó prefetch ni se filtraron errores. El diagnóstico del coordinador conservó 3/3 repeticiones y 0 errores de conexión con 6 conexiones TCP por caso (`../debug-loopback/keepalive.json`).', '', 'Esta tanda final ejecuta los mismos 18 casos canónicos con ese runner. QA ejecutó además los guardrails Node: 3/3 pasan, cero fallos/omitidos; incluyen aislamiento del entorno y reutilización de un socket para 20 recursos, preservando Host, cookies y POST al backend; también prueban la terminación de una respuesta si PHP corta el stream. Salida real en `raw/node-guardrails.txt`. La corrección afecta solo al entorno de pruebas; la compilación de la aplicación permanece estable.']
lines+=['', 'El intento 3 con keep-alive ya pasó 18/18 casos, conservados en raw/attempt-3/. La revisión posterior encontró un manejo incompleto de streams PHP interrumpidos en el runner. Tras corregirlo y verificar su regresión Node, esta ejecución final repite los 18 casos completos sobre el helper definitivo; no cuenta pases de ejecuciones anteriores.']
for identifier,project,status,duration,errors in records:
    if errors:
        lines+=['',f'### {identifier} · {project} · error','', '```', '\n'.join(errors)[:3000], '```']
lines+=['','## Trazabilidad','','| Tarea | Escenarios | Límite |','|---|---|---|','| T-03 | E2E-01; M-01 | Recolección real del VPS pendiente |','| T-04 | E2E-02, E2E-04 | E2E del flujo integrado; ownership en pruebas de servicio aparte |','| T-05 | E2E-03 | No valida capacidades avanzadas de T-09–20 |','| T-06 | E2E-02, E2E-03, E2E-04 | Tres viewports |','| T-07 | E2E-02, E2E-03, E2E-05; M-03 | Linux/R2 pendiente |','| T-08 | E2E-02–05 | API/MCP y contratos se verifican aparte |','| T-21 | E2E-06 | Solo coherencia de marca de este bloque |','','## Checklist manual pendiente','','- [ ] **M-01 — Usuario:** scheduler/worker del VPS, heartbeat y capturas recientes del periodo cerrado.','- [ ] **M-02 — Usuario:** publicación real por red y smokes Bluesky/Threads pendientes.','- [ ] **M-03 — Desarrollo + usuario:** renderer de producción con Node/Chromium/fuentes/cola media y archivo real con imagen/vídeo local y R2.','- [ ] **M-04 — Usuario, aplazado:** Claude Desktop.','','No se solicita SSH ni se ejecutan estas verificaciones externas. El bloque local no certifica operación en producción ni paridad completa.','','## PDF','','Se aplica el flujo de la skill `to-pdf` con su tema CSS: Markdown → HTML mediante League/CommonMark instalado → Chromium de Playwright instalado. Sustitución local del adaptador Puppeteer/markdown-it sin instalar dependencias; mismas capturas embebidas y contenido del informe. `render-report.php` y `render-report.mjs` permiten reproducirlo.']
(root/'report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
shutil.copy2(raw/'results.json',root/'results.json')
